599	async fn prepare_realtime_start(
600	    sess: &Arc<Session>,
601	    params: ConversationStartParams,
602	) -> CodexResult<PreparedRealtimeConversationStart> {
603	    let provider = sess.provider().await;
604	    let auth_manager = sess
605	        .services
606	        .model_client
607	        .auth_manager()
608	        .unwrap_or_else(|| Arc::clone(&sess.services.auth_manager));
609	    let auth = auth_manager.auth().await;
610	    let config = sess.get_config().await;
611	    let transport = params
612	        .transport
613	        .unwrap_or(ConversationStartTransport::Websocket);
614	    let mut api_provider = provider.to_api_provider(Some(AuthMode::ApiKey))?;
615	    if let Some(realtime_ws_base_url) = &config.experimental_realtime_ws_base_url {
616	        api_provider.base_url = realtime_ws_base_url.clone();
617	    }
618	    let version = config.realtime.version;
619	    let session_config = build_realtime_session_config(
620	        sess,
621	        params.prompt,
622	        params.session_id,
623	        params.output_modality,
624	        params.voice,
625	    )
626	    .await?;
627	    let requested_session_id = session_config.session_id.clone();
628	    let extra_headers = match transport {
629	        ConversationStartTransport::Websocket => {
630	            let realtime_api_key = realtime_api_key(auth.as_ref(), &provider)?;
631	            realtime_request_headers(
632	                requested_session_id.as_deref(),
633	                Some(realtime_api_key.as_str()),
634	            )?
635	        }
636	        ConversationStartTransport::Webrtc { .. } => {
637	            realtime_request_headers(requested_session_id.as_deref(), /*api_key*/ None)?
638	        }
639	    };
640	    Ok(PreparedRealtimeConversationStart {
641	        api_provider,
642	        extra_headers,
643	        requested_session_id,
644	        version,
645	        session_config,
646	        transport,
647	    })
